-- 3D sun view: a 1.5 km close-up box with water at Emily's Pond Levee (Wilson, WY, shot E2 'snake') (22 Nov 2026; NOT applied).
-- Before applying: upload these 4 files (1,185,627 bytes) to the public bucket `terrain`: gtd_emilys_pond_levee_lidar_v4.png, gtd_emilys_pond_levee_mask_v4.png, gtd_emilys_pond_levee_water_v4.png, gtd_emilys_pond_levee_colour_v4.jpg.
-- Built by tools/sun3d/build_dem_detail.py for the stand spot 43.513979, -110.828615, which lies outside every
-- laser point cloud (the 2022 park survey ends at lat 43.538; the 2014 Grand Teton / Elk Refuge survey has no data within 3 km):
--   heights: USGS 3DEP 1/3 arc-second DEM (~10 m, cubic to 1 m);
--   mask: 0 ground / 3 water only (no trees, no buildings); water from the NAIP photo's near-infrared, kept only where it lies
--   at the local low and in patches; water cells flattened to a smooth level. Box water 218,776 m2 (145,400 moving, 51,846 still).
--   water_path: the 6 km around at 4 m, 1 moving (the Snake River and what joins it) / 2 still (ponds): 92.2 ha (42.9 ha still).
--   color_path: NAIP turned to late December with tools/sun3d/teton_colour/build_teton_colour.py winterize (its fine-box branch:
--   conifers stay dark, no survey trees are drawn here), the mask's water painted the laser boxes' water colour.
-- Same table and formats as the laser boxes (terrain_detail_regions_v4, 20261114010000_terrain_sharp_teton.sql); leaf_mask_path stays null.
insert into public.terrain_detail_regions_v4 (id, parent, north, south, west, east, n, width_m, depth_m, base_m, step_m, cell_m, path, bytes, mask_path, mask_bytes, trees_path, trees_bytes, trees_bins, trees_bin_m, water_path, water_bytes, water_n, water_north, water_south, water_west, water_east, color_path, color_bytes, bare, note) values
  ('gtd15_emilys_pond_levee', 'grand_teton', 43.520746, 43.507212, -110.83793, -110.8193, 1504, 1504.0, 1504.1, 1872, 0.02, 1.0, 'gtd_emilys_pond_levee_lidar_v4.png', 486880, 'gtd_emilys_pond_levee_mask_v4.png', 15146, null, null, null, null, 'gtd_emilys_pond_levee_water_v4.png', 16201, 1500, 43.540974, 43.486984, -110.865776, -110.791454, 'gtd_emilys_pond_levee_colour_v4.jpg', 667400, true, 'USGS 3DEP 1/3 arc-second DEM (~10 m, cubic to 1 m), 1.5 km at 1 m. No point cloud here (no trees, no buildings). Water from USDA NAIP near-infrared checked against the heights, flattened.')
on conflict (id) do update set parent = excluded.parent, north = excluded.north, south = excluded.south, west = excluded.west, east = excluded.east, n = excluded.n, width_m = excluded.width_m, depth_m = excluded.depth_m, base_m = excluded.base_m, step_m = excluded.step_m, cell_m = excluded.cell_m, path = excluded.path, bytes = excluded.bytes, mask_path = excluded.mask_path, mask_bytes = excluded.mask_bytes, trees_path = excluded.trees_path, trees_bytes = excluded.trees_bytes, trees_bins = excluded.trees_bins, trees_bin_m = excluded.trees_bin_m, water_path = excluded.water_path, water_bytes = excluded.water_bytes, water_n = excluded.water_n, water_north = excluded.water_north, water_south = excluded.water_south, water_west = excluded.water_west, water_east = excluded.water_east, color_path = excluded.color_path, color_bytes = excluded.color_bytes, bare = excluded.bare, note = excluded.note;
